import refrom pathlib import Pathfrom typing import Optional, Dictimport pandas as pdfrom swat_toolkit.utils.logger import Loggerfrom swat_toolkit.utils.data_info import DATAParameterlogger = Logger.get_logger(__name__)class ReadFileLine:    ENCODINGS = ['utf-8', 'latin-1', 'windows-1252', 'cp1252', 'iso-8859-1']    def __init__(self):        pass    def _read_file(self, file_path: str, first_line: bool = False):        for encoding in self.ENCODINGS:            try:                with open(file_path, 'r', encoding=encoding) as file:                    if first_line:                        return file.readline()                    else:                        return [line for line in file]            except (UnicodeDecodeError, UnicodeError):                continue            except Exception as e:                logger.error(f"Error reading {file_path} with {encoding}: {e}")                continue        try:            with open(file_path, 'r', encoding='latin-1', errors='replace') as file:                logger.warning(f"Reading {file_path} with latin-1 and error replacement")                if first_line:                    return file.readline()                else:                    return [line for line in file]        except Exception as e:            raise IOError(f"Could not read file {file_path} with any encoding: {e}")    def _detect_encoding(self, file_path: str) -> str:        for encoding in self.ENCODINGS:            try:                with open(file_path, 'r', encoding=encoding) as file:                    file.read()                return encoding            except (UnicodeDecodeError, UnicodeError):                continue        # Default to latin-1 if nothing works        Logger.warning(f"Could not detect encoding for {file_path}, using latin-1")        return 'latin-1'    def _split_space(self, line: str):        return re.split(r'\s+', line)    def _split_ext(self, df: pd.DataFrame, col_name: str):        df[['param', 'ext']] = df[col_name].str.rsplit('.', n=1, expand=True)        return df    def _read_hru_attribute(self, line: str) -> Optional[Dict]:        pattern = (            r"Watershed HRU:(?P<Watershed>\d+)\s+"            r"Subbasin:(?P<Subbasin>\d+)\s+"            r"HRU:(?P<HRU>\d+)\s+"            r"Luse:(?P<Luse>[A-Za-z0-9_]+)\s+"            r"Soil:\s*(?P<Soil>[A-Za-z0-9\-_]+)\s+"            r"Slope:\s*(?P<Slope>[0-9\-]+)"        )        match = re.search(pattern, line)        if not match:            return None        return match.groupdict()class HRURead(ReadFileLine):    def __init__(self, file_path: str):        super().__init__()        self.hru_file = file_path        self.lines = self._read_file(file_path)    def get_value(self, param: DATAParameter):        line = self.lines[param.line]        value = line[param.start : param.end].strip()        return value